 type UnknownRecord = Record<string, unknown>;

 const LOBU_VIEW_SNAPSHOT_KEY = "lobuViewSnapshot";
 const LOBU_VIEW_SNAPSHOT_VERSION = 1;

 export interface OpenAiCompatSnapshot<T> {
 	/** `undefined` means the host did not update this global. */
 	data: T | null | undefined;
 	/** `undefined` means the host did not update this global. */
 	approvalCapability: string | null | undefined;
 }

+function snapshotCapabilityFromMeta(meta: unknown): string | null {
+	if (!isStructuredObject(meta)) return null;
+	const token = meta["lobu/mcp-app-snapshot-capability"];
+	if (typeof token !== "string") return null;
+	const normalized = token.trim();
+	return normalized && normalized.length <= 512 ? normalized : null;
+}
+
 function isStructuredObject(value: unknown): value is UnknownRecord {
 	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
 }

 export function approvalCapabilityFromMeta(meta: unknown): string | null {
 	if (!isStructuredObject(meta)) return null;
 	const token = meta["lobu/approval-capability"];
 	return typeof token === "string" && token.length <= 4_096 ? token : null;
 }

 function approvalCapabilityFromResult(result: unknown): string | null {
 	if (!isStructuredObject(result)) return null;
 	return approvalCapabilityFromMeta(result._meta);
 }

+function snapshotCapabilityFromResult(
+	result: unknown,
+): string | null | undefined {
+	if (!isStructuredObject(result) || !Object.hasOwn(result, "_meta"))
+		return undefined;
+	return snapshotCapabilityFromMeta(result._meta);
+}
+
+/** Read the opaque per-result restore key from ChatGPT compatibility globals. */
+export function snapshotCapabilityFromOpenAiGlobals(
