+	);
+	const metadata = isStructuredObject(globals.toolResponseMetadata)
+		? globals.toolResponseMetadata
+		: null;
+	if (hasToolResponseMetadata) {
+		return metadata
+			? (snapshotCapabilityFromResult(metadata.mcp_tool_result) ??
+					snapshotCapabilityFromResult(metadata.call_tool_result) ??
+					null)
+			: null;
+	}
+	return hasFullToolResult
+		? snapshotCapabilityFromResult(globals.toolOutput)
+		: undefined;
+}
+
 function dataFromToolOutput<T>(toolOutput: unknown): T | null {
 	if (!isStructuredObject(toolOutput)) return null;
 	if (Object.hasOwn(toolOutput, "structuredContent")) {
 		return isStructuredObject(toolOutput.structuredContent)
 			? (toolOutput.structuredContent as T)
 			: null;
 	}
 	return toolOutput as T;
