   369	
   370	async function saveMcpAppStateImpl(
   371		args: {
   372			tool_call_id?: string | number;
   373			snapshot_capability?: string;
   374			tool_name?: string;
   375			view_state: UnknownRecord;
   376		},
   377		_env: Env,
   378		ctx: ToolContext,
   379	) {
   380		const identity =
   381			args.tool_call_id === undefined
   382				? null
   383				: snapshotIdentity(ctx, args.tool_call_id);
   384		const viewState = boundedMcpAppViewState(args.view_state);
   385		const sql = getDb();
   386		const bindingIdentity = snapshotIdentity(
   387			ctx,
   388			// Some hosts preserve their own request metadata but intentionally strip
   389			// app-supplied metadata. This private app-only argument keeps the one-time
   390			// capability end to end; metadata remains supported for standard hosts.
   391			args.snapshot_capability ?? ctx.mcpAppSnapshotCapability,
   392		);
   393		if (!identity && !bindingIdentity) return { saved: false };
   394		if (!identity && bindingIdentity) {
   395			try {
   396				return await sql.begin(async (tx) => {
   397					const candidates = await tx<SnapshotLookupRow>`
   398						SELECT body, tool_name, tool_call_key
   399						FROM public.mcp_app_result_snapshots
   400						WHERE organization_id = ${bindingIdentity.organizationId}
   401							AND client_id = ${bindingIdentity.clientId}
   402							AND user_id = ${bindingIdentity.userId}
   403							AND conversation_key = ${bindingIdentity.conversationKey}
   404							AND expires_at > now()
   405						ORDER BY updated_at DESC, tool_call_key
   406						LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
   407						FOR UPDATE
   408					`;
   409					const row = candidates.find((candidate) => {
   410						const snapshot = parseSnapshot(candidate.body);
   411						return snapshot?.bindingKey === bindingIdentity.toolCallKey;
   412					});
   413					if (!row || (args.tool_name && row.tool_name !== args.tool_name))
   414						return { saved: false };
   415					const snapshot = parseSnapshot(row.body);
   416					if (!snapshot || snapshot.toolName !== row.tool_name)
   417						return { saved: false };
   418					const serialized = serializeSnapshot({ ...snapshot, viewState });
   419					if (!serialized) return { saved: false };
   420					const updated = await tx`
   421						UPDATE public.mcp_app_result_snapshots
   422						SET tool_call_key = ${bindingIdentity.toolCallKey},
   423							body = ${serialized.body},
   424							plaintext_bytes = ${serialized.plaintextBytes},
   425							updated_at = now()
   426						WHERE organization_id = ${bindingIdentity.organizationId}
   427							AND client_id = ${bindingIdentity.clientId}
   428							AND user_id = ${bindingIdentity.userId}
   429							AND conversation_key = ${bindingIdentity.conversationKey}
   430							AND tool_call_key = ${row.tool_call_key}
   431					`;
   432					return { saved: updated.count === 1 };
   433				});
   434			} catch (error) {
   435				if (!isRecord(error) || error.code !== "23505") throw error;
   436				logger.warn(
   437					{ toolName: args.tool_name },
   438					"MCP App capability key collision; candidate restore disabled",
   439				);
   440				return { saved: false };
   441			}
   442		}
   443		if (!identity) return { saved: false };
   444		if (
   445			bindingIdentity &&
   446			bindingIdentity.toolCallKey !== identity.toolCallKey
   447		) {
   448			try {
   449				return await sql.begin(async (tx) => {
   450					const [candidate] = await tx<SnapshotRow>`
   451						SELECT body, tool_name
